#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    scripts/..., scripts/calculators
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * What does an installed copy of this package actually contain, and how much of it can a
 * consumer reach?
 *
 * `files: ["dist", ...]` ships the whole build output, but only what the `exports` map
 * names is importable. Anything else is weight in the tarball that no user can load — and
 * worse, it is where an import of a package that is not published can hide, because
 * nothing reachable ever evaluates it.
 *
 * Walks the module graph from every public entry point and reports:
 *   - modules a consumer can reach
 *   - shipped modules they cannot
 *   - any reachable module importing something outside `dependencies`
 *
 *   node scripts/audit-published-surface.mjs [--json]
 */
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

/**
 * `from '...'`, `import('...')` and `require('...')`.
 *
 * The build emits CommonJS, so nearly every edge in `dist` is a `require()` — matching only
 * ESM syntax made the whole package look like eleven reachable modules, which would have
 * declared 469 files dead that are not.
 */
const SPECIFIER = /(?:\bfrom\s*|\bimport\s*\(\s*|\brequire\s*\(\s*)['"]([^'"]+)['"]/g

/** The `.js` files npm would put in the tarball, honouring `files` and its exclusions. */
function packedFiles() {
  const raw = execFileSync('npm', ['pack', '--dry-run', '--json'], {
    cwd: PACKAGE_ROOT,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
    shell: process.platform === 'win32',
  })
  const [manifest] = JSON.parse(raw)
  return manifest.files.map(entry => path.join(PACKAGE_ROOT, entry.path))
}

function resolveRelative(fromFile, specifier) {
  const base = path.resolve(path.dirname(fromFile), specifier)
  if (existsSync(`${base}.js`)) return `${base}.js`
  if (existsSync(path.join(base, 'index.js'))) return path.join(base, 'index.js')
  return existsSync(base) ? base : null
}

function main() {
  const pkg = JSON.parse(readFileSync(path.join(PACKAGE_ROOT, 'package.json'), 'utf8'))
  const declared = new Set([
    ...Object.keys(pkg.dependencies ?? {}),
    ...Object.keys(pkg.peerDependencies ?? {}),
  ])

  const named = Object.entries(pkg.exports ?? {})
    .filter(([key]) => !key.includes('*') && !key.endsWith('.json'))
    .map(([, value]) => (typeof value === 'string' ? value : value.import ?? value.default ?? value.require))
    .filter(Boolean)
    .map(target => path.resolve(PACKAGE_ROOT, target))

  /*
   * Wildcard subpaths are entry points too.
   *
   * `./internal/*` makes every module under `dist/internal` importable, but skipping the pattern
   * left all of them looking dead — the audit reported `internal/game-input-data/index.js` as
   * unreachable while `thetowersdk/internal/game-input-data` resolves perfectly well. A reader
   * chasing that would delete something a consumer can import.
   */
  const wildcards = Object.entries(pkg.exports ?? {})
    .filter(([key]) => key.includes('*'))
    .map(([, value]) => (typeof value === 'string' ? value : value.import ?? value.default ?? value.require))
    .filter(Boolean)
    .flatMap((target) => {
      const prefix = path.resolve(PACKAGE_ROOT, String(target).replace(/\*.*$/, ''))
      const collect = dir => (existsSync(dir)
        ? readdirSync(dir, { withFileTypes: true }).flatMap(item => (item.isDirectory()
            ? collect(path.join(dir, item.name))
            : (item.name.endsWith('.js') ? [path.join(dir, item.name)] : [])))
        : [])
      return collect(prefix)
    })

  const entries = [...new Set([...named, ...wildcards])]

  /*
   * Reachability is bounded by what ships. A module excluded from `files` exists on this
   * machine but not in anyone's `node_modules`, so following an edge into it would report
   * a consumer can reach code that is not in their install — and would keep reporting the
   * excluded governance modules as reachable forever.
   */
  /*
   * Everything in the tarball, and separately the JavaScript in it.
   *
   * Reachability walks modules, so it wants the JS. The dangling-require check below needs to know
   * about EVERY shipped file — its first version inherited the `.js` filter and reported eight
   * `.json` data files as missing when they ship perfectly well, which would have made the whole
   * check something a reader learns to ignore.
   */
  const allShipped = packedFiles()
  const allShippedSet = new Set(allShipped)
  const shipped = allShipped.filter(file => file.endsWith('.js'))
  const shippedSet = new Set(shipped)

  const reachable = new Set()
  const external = new Map()
  const stack = entries.filter(entry => shippedSet.has(entry))

  while (stack.length > 0) {
    const file = stack.pop()
    if (!file || reachable.has(file) || !existsSync(file) || !shippedSet.has(file)) continue
    reachable.add(file)

    const source = readFileSync(file, 'utf8')
    for (const match of source.matchAll(SPECIFIER)) {
      const specifier = match[1]
      if (!specifier) continue
      if (specifier.startsWith('.')) {
        const resolved = resolveRelative(file, specifier)
        if (resolved) stack.push(resolved)
        continue
      }
      if (specifier.startsWith('node:')) continue
      /*
       * Prose in this package quotes phrases with `from '...'` in it, and a plain regex
       * reads those as imports — "not a league" was reported as a missing dependency.
       * A real specifier has no whitespace and is a valid package name.
       */
      if (!/^(?:@[\w.-]+\/)?[\w.-]+(?:\/[\w.-]+)*$/.test(specifier)) continue
      const packageName = specifier.startsWith('@')
        ? specifier.split('/').slice(0, 2).join('/')
        : specifier.split('/')[0]
      if (packageName === pkg.name) continue // self-reference across its own subpaths
      if (!external.has(packageName)) external.set(packageName, new Set())
      external.get(packageName).add(path.relative(PACKAGE_ROOT, file).split(path.sep).join('/'))
    }
  }

  const unreachable = shipped.filter(file => !reachable.has(file))
  const rel = file => path.relative(PACKAGE_ROOT, file).split(path.sep).join('/')

  /*
   * A shipped module must not require something that is not shipped.
   *
   * Reachability above walks OUT from the exports map, so it never visits a module no public entry
   * point imports — and `mcp/` ships without being in that map. `dist/mechanics/calculators/
   * registry.js` requires `./specs-generated`, which `files` excludes at 1.8 MB, and the MCP
   * server requires that directory at runtime through a computed path a static walk cannot follow.
   *
   * The result: the entire MCP server threw MODULE_NOT_FOUND for anyone who installed the package,
   * while every check here passed. Neither half was wrong alone — the exclusion and the require
   * landed in separate commits — and nothing compared the two.
   *
   * This asks a different question from reachability, and one that needs no entry point: of the
   * files actually in the tarball, does every relative require resolve to another file in the
   * tarball?
   */
  const dangling = []
  for (const file of shipped) {
    if (!/\.(js|mjs|cjs)$/.test(file)) continue
    /*
     * Comments stripped first, for the reason the specifier regex already carries a note about:
     * this package's prose quotes module paths. `dist/mechanics/index.js` explains at length why
     * it does NOT `export * from './calculators'`, and reading that explanation as a require
     * reported the public mechanics entry point as broken when it loads perfectly well.
     */
    const source = readFileSync(file, 'utf8')
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/^\s*\/\/.*$/gm, '')
    for (const match of source.matchAll(SPECIFIER)) {
      const specifier = match[1]
      if (!specifier || !specifier.startsWith('.')) continue
      const resolved = resolveRelative(file, specifier)
      if (!resolved || !allShippedSet.has(resolved)) {
        dangling.push(`${rel(file)} requires ${specifier}, which is not in the tarball`)
      }
    }
  }
  const undeclared = [...external].filter(([name]) => !declared.has(name))

  const report = {
    /*
     * Named entry points, and the wildcard-expanded modules kept separate.
     *
     * Counting them together reported "entryPoints: 500" for a package with fourteen — the
     * wildcard makes every module under `dist/internal` a valid specifier, which is a fact about
     * reachability rather than about how many doors the package has.
     */
    entryPoints: named.length,
    reachableViaWildcard: wildcards.length,
    reachable: reachable.size,
    shipped: shipped.length,
    unreachable: unreachable.map(rel).sort(),
    danglingRequires: [...new Set(dangling)].sort(),
    undeclaredImports: Object.fromEntries(undeclared.map(([name, files]) => [name, [...files].sort()])),
  }

  if (process.argv.includes('--json')) {
    console.log(JSON.stringify(report, null, 2))
    return
  }

  console.log(`Entry points:        ${report.entryPoints} named, +${report.reachableViaWildcard} via wildcard`)
  console.log(`Reachable modules:   ${report.reachable}`)
  console.log(`Shipped dist modules:${String(report.shipped).padStart(5)}`)
  console.log(`Unreachable:         ${report.unreachable.length}`)

  console.log(`Dangling requires:   ${report.danglingRequires.length}`)

  if (report.danglingRequires.length > 0) {
    console.log('\nShipped modules requiring files that are NOT in the tarball:')
    for (const line of report.danglingRequires.slice(0, 15)) console.log(`  ${line}`)
    if (report.danglingRequires.length > 15) {
      console.log(`  … and ${report.danglingRequires.length - 15} more`)
    }
    console.log('\nEither ship the missing file, or stop shipping the module that requires it.')
    process.exitCode = 1
  }

  if (undeclared.length > 0) {
    console.log('\nReachable code imports packages that are not declared dependencies:')
    for (const [name, files] of undeclared) {
      console.log(`  ${name}`)
      for (const file of [...files].sort().slice(0, 5)) console.log(`    ${file}`)
    }
    process.exitCode = 1
  }

  /*
   * Nothing that SHIPS may reference a package that is not on the registry. Six modules
   * once did — a top-level `require("@tmrxjd/governance-engine")` that throws
   * "Cannot find module" in any real install. They were invisible because the `exports`
   * map does not reach them, so every entry point imported fine and the tarball was
   * broken anyway. `files` now excludes them; this is what keeps them excluded.
   */
  const unpublished = shipped.filter(file => readFileSync(file, 'utf8').includes('@tmrxjd/'))
  if (unpublished.length > 0) {
    console.log('\nShipped modules referencing an unpublished workspace package:')
    for (const file of unpublished.map(rel).sort()) console.log(`  ${file}`)
    console.log('\nExclude them in package.json "files", or remove the dependency.')
    process.exitCode = 1
  }
}

main()
